package earth.terrarium.pastel.data.lang.guidebook.equipment;

import net.neoforged.neoforge.common.data.LanguageProvider;

public class IncandescentAmalgamEntry {
	public static void addTranslations(LanguageProvider provider) {
		provider.add("book.pastel.guidebook.incandescent_amalgam.page0.text", "*The sun on the palm of my hand* sounded far better in theory. \\\n\\\nNow that it sits there... well, it burns. The very fact that it exists is almost a miracle - really, it should have exploded in the barrel - an unstable, simmering amalgam of ethanol blended with a cocktail of accelerants that hates existing.");
		provider.add("book.pastel.guidebook.incandescent_amalgam.page1.text", "One false move could easily cause it to detonate, taking everything nearby with it, including me. And yet, for all these reasons and more, the soft, warm glow of the gel elicits endless curiosity. All things are drawn to the flame.\\\n\\\nThere is no question that what is effectively a high-yield magical explosive bears endless potential. All I need is a little care, a small mountain of it, and a touch of reckless abandon.");
		provider.add("book.pastel.guidebook.incandescent_amalgam.page2.text", "The longer the synthesis goes on, the higher the yield... I really can't blame the angels for not wanting their share of this.");
		provider.add("book.pastel.guidebook.incandescent_amalgam.page2.title", "Titration Synthesis");
		provider.add("book.pastel.guidebook.incandescent_amalgam.page3.text", "*...so grossly incandescent!*");
		provider.add("book.pastel.guidebook.incandescent_amalgam.page3.title", "Pure Synthesis");
		provider.add("book.pastel.guidebook.incandescent_amalgam.page4.title", "Simple Synthesis");
		provider.add("book.pastel.guidebook.incandescent_amalgam.page5.text", "The amalgam's pristine burn makes it uniquely suited to Pure Alcohol distillation");
		provider.add("book.pastel.guidebook.incandescent_amalgam.page5.title", "Distillation");
	}
}
